-- 区域升级时:
function UIActionConstructDialog:OnBtnLevelUp()    
    self._idleTime = 0
    local isCanUp = ActionUtils.IsCanLevelUp()
    if not isCanUp then
        GameUtils.Toast(localize("需要完成当前所有任务"))
        return
    end
    local isMax = ActionUtils.IsMaxLikabilityLevel(self._curMapId)
    if isMax then
        GameUtils.Toast(localize("已经是最大等级"))
        return
    end

    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._curMapId)
    local vo = ActionUtils.GetRegionLikabilityVo(ActionUtils.GetRegionLikabilityId(self._curMapId, lv))
    if GoodsUtils.GetThingNo(vo.levelUpCost) < checkNumber(vo.levelUpNum) then
        GoodsUtils.ShowCommonLackMaterialDialog({{ goodsId = vo.levelUpCost, num = vo.levelUpNum }})
        return
    end

    ActionComponent:OverseaRegionalMapUpgradeReq(self._curMapId, function(rewards)
        self:InitData()
        self:FillTaskInfo()
        self:FillLikabilityInfo()

        GoodsUtils.DrawRewards(rewards, true)
        GoodsUtils.DrawRewards({ { goodsId = vo.levelUpCost, num = -checkNumber(vo.levelUpNum) } }, true)

        local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._curMapId)
        UIModule.OpenDialog(
            { 
                id = Constants.UITypeIds.UIActionImpressionDialog, 
                parameters = { id = self._curMapId, targetLv = lv, cb = function()
                    CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop2, parameters = { rewards = rewards, type = 1, cb = function()
                        self:FillList(true)
                        ActionComponent:OverseaRegionalHomeReq()
                    end} })
                end}
            }, 
            {}
        )
    end)
end

