function UIActionConstructDialog:InitData()    
    self._allTask = {}

    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._curMapId)
    local isMax = ActionUtils.IsMaxLikabilityLevel(self._curMapId)

    local t = {}
    if isMax then
        local _t = ActionUtils.GetAllTaskByLevelAndId(self._curMapId, lv - 1)
        for k, id in pairs(_t) do
            local vo = ActionUtils.GetRegionTaskVo(id)
            if vo then
                if not (t[checkString(vo.taskGroup)]) then
                    t[checkString(vo.taskGroup)] = {}
                end
                table.insert(t[checkString(vo.taskGroup)], {
                    taskId = vo.id, 
                    status = 2,
                    progress = vo.progress,
                })  
            end
        end
    else
        t = ActionComponent:GetAllTask()
    end


    for k, v in pairs(t) do
        local sortKey = 3
        local proNum = 0

        local _t = {}
        for _, taskData in pairs(v) do
            local isUnlock = ActionUtils.IsUnlockTask(taskData.taskId)
            if isUnlock then
                local vo = ActionUtils.GetRegionTaskVo(taskData.taskId)
                local num = checkNumber(taskData.progress) / checkNumber(vo.taskContenNum)
                if num > proNum then
                    proNum = num
                end
                if taskData.status == 0 then
                    taskData.sortKey = 2 --2
                    if 2 < sortKey then
                        sortKey = 2
                    end
                elseif taskData.status == 1 then
                    taskData.sortKey = 2 --1
                    if 1 < sortKey then
                        sortKey = 1
                    end
                elseif taskData.status == 2 then
                    taskData.sortKey = 2 --3
                    if 3 < sortKey then
                        sortKey = 3
                    end
                end
            end

            table.insert(_t, taskData)
        end

        table.sort(_t, function(a, b)
            --if checkNumber(a.sortKey) == checkNumber(b.sortKey) then
                return checkNumber(a.taskId) < checkNumber(b.taskId)
            --else
            --    return checkNumber(a.sortKey) < checkNumber(b.sortKey)
            --end
        end)

        local data, curInd = self:GetTopTask(_t)
        local vo = ActionUtils.GetRegionTaskVo(data.taskId)
        table.insert(self._allTask, {
            id = k, 
            data = _t,
            sortKey = sortKey,
            proNum = checkNumber(data.progress) / checkNumber(vo.taskContenNum),
            curInd = curInd
        })
    end
    table.sort(self._allTask, function(a, b)
        if checkNumber(a.sortKey) ~= checkNumber(b.sortKey) then
            return checkNumber(a.sortKey) < checkNumber(b.sortKey)
        elseif checkNumber(a.sortKey) == checkNumber(b.sortKey) and checkNumber(a.sortKey) == 2 then
            if strict_number_equal(checkNumber(b.proNum), checkNumber(a.proNum)) then
                if strict_number_equal(checkNumber(b.curInd), checkNumber(a.curInd)) then
                    return checkNumber(a.id) < checkNumber(b.id)
                else
                    return checkNumber(b.curInd) < checkNumber(a.curInd)
                end
            else
                return checkNumber(b.proNum) < checkNumber(a.proNum)
            end
        end
        return checkNumber(a.id) < checkNumber(b.id)
    end)
end

