function UIActionConstructDialog:FillTaskInfo()
    local isMax = ActionUtils.IsMaxLikabilityLevel(self._curMapId)
    if isMax then
        local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._curMapId)

        local num1, num2 = ActionUtils.GetTaskNumBuyHomeData(self._curMapId, lv - 1)
        CfUtils.FillText(self.TxtprogressNum, localize("_num1_<color=#ffffff><size=40>/_num2_", {_num1_ = num2, _num2_ = num2}))
    else
