function UIActionConstructDialog:FillList(isUp)
    self._isUp = checkBool(isUp)
    self:RefreshListData()

    if not self.ListView.IsListViewInit then
        self.ListView:InitListView(#self._listData, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ListView, #self._listData)
    end
    local num1, num2 = ActionUtils.GetTaskFinishNum()
    CfUtils.SetActive(self.FinishGroup, num1 >= num2)
    CfUtils.SetActive(self.FontStyleButton1, num1 < num2)
end

function UIActionConstructDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell 
    
    local data = self._listData[index + 1]
    if data.type == 1 then
        cell = listView:NewListViewItem("CellNode2")
    else
        cell = listView:NewListViewItem("CellNode1")
    end

    if index > 3 then
        self._isUp = false
    end
    if data.type == 2 then
        local go = cell.gameObject
        local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.UIActionConstructDialog.UIActionConstructNode")
        if scr then
            scr:Refresh(data, self._isExpland, function(rewards)
                self:InitData()
                self:FillList()
                self:FillTaskInfo()
                local isHave = ActionUtils.IsAreaHaveRedPoint(self._curMapId)
                GameUtils.SetRedPointNum(Constants.RedPointConst["MaidCoffeeAreaMap"..self._curMapId], isHave and 1 or 0)
                CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards, cb = function()
                    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._curMapId)
                    local isMax = ActionUtils.IsMaxLikabilityLevel(self._curMapId)
                    local isCanUp = (ActionUtils.IsCanLevelUp() and not isMax)
                    if isCanUp then
                        CfUtils.SetActive(self.LeftPanel.transform:Find("Panel/ButtonGroup/UIFX_Updates"), true)
                    end
                    self:FillLikabilityInfo()

                    self:PlayStoreAni(StoreStatus.Type13)
                end } })
            end, self._isUp)
        end

        local t = ActionUtils.GetAllGroupTask(data.groupId)
        local isTrue = (table.count(t) > 1 and not self._isExpland)
        local rt = go.gameObject:GetComponent(typeof(RectTransform))
        if isTrue then
            rt:SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, 184)
        else
            rt:SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, 169)
        end
    end
    cell.gameObject.transform:SetAsLastSibling()
    return cell
end

function UIActionConstructDialog:RefreshListData()
    self._listData = {}
    if self._isExpland then
        for k, v in pairs(self._allTask) do
            if table.count(self._listData) > 0 then 
                table.insert(self._listData, {
                    type = 1, 
                    data = v.id,
                })
            end

            for ind, task in pairs(v.data) do
                task.type = 2 
                task.groupId = v.id 
                task.ind = ind 

                table.insert(self._listData, task)
            end
        end
    else
        for k, v in pairs(self._allTask) do
            local data = self:GetTopTask(v.data)
            data.type = 2
            data.groupId = v.id
            data.ind = 0

            table.insert(self._listData, data)
        end
    end
end

--最上面的任务
function UIActionConstructDialog:GetTopTask(t)
    local ind = 0
    for k, v in pairs(t) do
        if ActionUtils.IsUnlockTask(v.taskId) and not ActionUtils.IsDrawTask(v.taskId) then
            return t[k], t[k]
        end
    end
    --代表都做完了
    if ind == 0 then
        ind = table.count(t)
    end
    return t[ind], nil--t[k]--(ind / table.count(t))
end

function UIActionConstructDialog:FillRoleInfo()
    local vo = ActionUtils.GetRegionStoresVo(self._curMapId)
    local loader = ResourceModule.LoadBundleAsync(vo.resource, nil, true)
    while not loader.IsSuccess do
        cs_coroutine.yield_return()
    end
    if not loader.IsError then
        local go = loader:Instantiate(self.SpineScale.transform)
        go.transform.localPosition = Vector3(0, 0, 0)
        go.transform.localScale = Vector3(1, 1, 1)
        self._spineGo = go.gameObject:GetComponent(typeof(SkeletonGraphic))
    end

    loader:Release()
end

function UIActionConstructDialog:OnFixUpdate()
    self._idleTime = self._idleTime + CS.UnityEngine.Time.deltaTime
    --if self._idleTime > 7 then
    --    self._idleTime = 0
    --end
end

function UIActionConstructDialog:PlayStoreAni(aniType)
    if aniType == StoreStatus.Type13 then
        -->7才播放
        if self._idleTime < 7 then
            return
        else
            self._idleTime = 0
        end
    end

    self._curType = aniType

    if self._storeCo ~= nil then
        cs_coroutine.stop(self._storeCo)
        self._storeCo = nil
    end
    print(aniType)
    self._storeCo = cs_coroutine.start(function()
        local t = ActionUtils.GetAllAnimaorIdByActionId(self._curMapId, 3, aniType)
        if table.count(t) <= 0 then
            return
        end
        local num = math.random(table.count(t))
        local id = t[num]
    
        local vo = ActionUtils.GetRegionStoreAnimatorVo(id)
        if not vo then
            return
        end
        CfUtils.SetActive(self.DialogGroup, true)
    
        CfUtils.FillText(self.TxtState, vo.line)
        CfUtils.SetActive(self.DialogGroup, not string.isEmpty(checkString(vo.line)))

        GameUtils.GetCriWareUtils().PlayVoiceById(vo.soundEffects)

        print(vo.animation)
        local isLoop = (aniType == StoreStatus.Type1)
        CfUtils.PlaySpine(self._spineGo, vo.animation, isLoop)

        if aniType ~= StoreStatus.Type1 then
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(CfUtils.GetSpineTime(self._spineGo, vo.animation)))
            if checkNumber(self._nextType) > 0 then
                self:PlayStoreAni(self._nextType)
                self._nextType = 0
            else
                self:PlayStoreAni(StoreStatus.Type1)
            end
        end
    end)
end

--好感度信息
function UIActionConstructDialog:FillLikabilityInfo()
    local vo = ActionUtils.GetRegionPrimaryMapVo(self._curMapId)
    if not vo then
        return
    end
    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._curMapId)
    CfUtils.FillText(self.TxtLv, lv)
    local isMax = ActionUtils.IsMaxLikabilityLevel(self._curMapId)

    if isMax then
        CfUtils.SetActive(self.CommonBtnConsumePop, false)
        CfUtils.SetActive(self.FontStyleButton1, false)

        self.FontStyleButton:ResetFontStyle("B17", localize("区域已满级"))
        vo = ActionUtils.GetRegionLikabilityVo(ActionUtils.GetRegionLikabilityId(self._curMapId, lv - 1))
        CfUtils.FillText(self.TxtTitle, vo.name)

        local t = parse_rewards(vo.rewardGoods, vo.goodsNum)
        for k, v in pairs(t) do
            local go = self.GoodItem.transform:Find("go"..k)
            if not go then
                go = CfUtils.InstantiateGo(self.GoodNode, self.GoodItem)
                go.name = "go"..k
            end
    
            CfUtils.RefeshGoodGo2(go, v.goodsId, v.goodsNum, nil, nil, function()
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.goodsId)
                GameUtils.ShowCommonTipsBoard(go.transform:Find("Container"), goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
            end)
            local scr = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
            if scr then
                scr:SetSanXingGainShow(true)
            end
            CfUtils.SetActive(go, true)
        end
    else
        local isCanUp = (ActionUtils.IsCanLevelUp() and not isMax)

        vo = ActionUtils.GetRegionLikabilityVo(ActionUtils.GetRegionLikabilityId(self._curMapId, lv))
        CfUtils.FillText(self.TxtTitle, vo.name)
        KTool.SetActive(self.CommonBtnConsumePop.gameObject, checkNumber(vo.levelUpNum) > 0)
        if checkNumber(vo.levelUpNum) > 0 then
            CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, vo.levelUpCost, vo.levelUpNum, false)
        end
        --CfUtils.SetActive(self.CommonBtnConsumePop, isCanUp)
        if isCanUp then
            self.FontStyleButton:ResetFontStyle("B1")
        else
            self.FontStyleButton:ResetFontStyle("B17")
        end
    
        local t = parse_rewards(vo.rewardGoods, vo.goodsNum)
        for k, v in pairs(t) do
            local go = self.GoodItem.transform:Find("go"..k)
            if not go then
                go = CfUtils.InstantiateGo(self.GoodNode, self.GoodItem)
                go.name = "go"..k
            end
    
            CfUtils.RefeshGoodGo2(go, v.goodsId, v.goodsNum, nil, nil, function()
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.goodsId)
                GameUtils.ShowCommonTipsBoard(go.transform:Find("Container"), goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
            end)
            CfUtils.SetActive(go, true)
        end
    end
end

function UIActionConstructDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._curMapId)            
        local vo = ActionUtils.GetRegionLikabilityVo(ActionUtils.GetRegionLikabilityId(self._curMapId, lv))
        if checkNumber(vo.levelUpCost) > 0 then
            CfUtils.RefreshTopGoods({vo.levelUpCost})
        else
            CfUtils.RefreshTopGoods({})
        end

        self:PlayStoreAni(self:GetEnterSpineName())
    end))
    return coWait
end

function UIActionConstructDialog:GetEnterSpineName()
    local isCanUp = ActionUtils.IsCanLevelUp()
    if not isCanUp then
        return StoreStatus.Type5
    else
        local isMax = ActionUtils.IsMaxLikabilityLevel(self._curMapId)
        if isMax then
            return StoreStatus.Type8
        else
            local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._curMapId)
            local vo = ActionUtils.GetRegionLikabilityVo(ActionUtils.GetRegionLikabilityId(self._curMapId, lv))
            if GoodsUtils.GetThingNo(vo.levelUpCost) < checkNumber(vo.levelUpNum) then
                return StoreStatus.Type6
            else
                return StoreStatus.Type7
            end
        end
    end
    return StoreStatus.Type1
end

function UIActionConstructDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()

        -- 刷新数据, 方便正确显示 小红点
        ActionComponent:OverseaRegionalHomeReq()

        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._curMapId = checkNumber(argument.mapId)
        local vo = ActionUtils.GetRegionPrimaryMapVo(self._curMapId)
        if vo then
            CfUtils.FillImage(self.controller.gameObject.transform:Find("BackGround"), vo.taskImage)
        end

        local isFinish = false
        ActionComponent:OverseaRegionalMapTaskListReq(self._curMapId, function()
            isFinish = true
        end)

        while not isFinish do
            coroutine.yield()
        end
        self:InitData()
        self:FillSelf()

        self._behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
        self._behaviourAction.UpdateAction = function()
            self:OnFixUpdate()
        end
    end))
    return coWait
end

function UIActionConstructDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self._storeCo ~= nil then
            cs_coroutine.stop(self._storeCo)
            self._storeCo = nil
        end
        self._behaviourAction.UpdateAction = nil

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIActionConstructDialog
